# -*- coding: utf-8 -*-
import html
import json
import re
from pathlib import Path

root = Path("WEB-LMS-VS2010")
out = root / "lms-save-load-mapping-flow.html"
schema = json.loads(Path("graphify-out/_table_schema.json").read_text(encoding="utf-8"))
ms = (root / "LmsService/ModuleServices.cs").read_text(encoding="utf-8")

services = []
pat = re.compile(
    r"public sealed class (\w+) : ModuleService\s*\{\s*public \1\(\) : base\(Map\((.*?)\)\)",
    re.S,
)
for m in pat.finditer(ms):
    pairs = re.findall(r'"([^"]+)"\s*,\s*"([^"]+)"', m.group(2))
    services.append((m.group(1), pairs))


def e(s):
    return html.escape(str(s), quote=False)


def flow_step(title, desc, table=None, extra=None):
    tbl = f'<a class="tbl-link" href="#tbl-{e(table)}">{e(table)}</a>' if table else ""
    ex = f'<div class="step-extra">{extra}</div>' if extra else ""
    return (
        f'<div class="flow-step"><strong>{e(title)}</strong>'
        f'<p>{desc}</p>{tbl}{ex}</div><div class="flow-arrow" aria-hidden="true">→</div>'
    )


def flow_row(steps):
    parts = [flow_step(*s) for s in steps]
    if parts:
        parts[-1] = parts[-1].replace('<div class="flow-arrow" aria-hidden="true">→</div>', "")
    return '<div class="flow-row">' + "".join(parts) + "</div>"


nav = [
    ("sec-overview", "01", "Tổng quan"),
    ("sec-auth", "01", "Đăng nhập & phân quyền"),
    ("sec-academic", "03", "Cơ cấu đào tạo"),
    ("sec-build", "02", "Dựng khóa học"),
    ("sec-lesson", "B", "Học liệu & học viên"),
    ("sec-forms", "04", "Form CMS → SP"),
    ("sec-sp", "05", "Map operation → SP"),
    ("sec-relations", "07", "Quan hệ dữ liệu"),
    ("sec-tables", "08", "Danh mục bảng & cột"),
    ("sec-rules", "09", "Quy tắc quan trọng"),
]

sp_rows = []
for svc, pairs in services:
    for op, sp in pairs:
        sp_rows.append(f"<tr data-search='{e(svc)} {e(op)} {e(sp)}'><td><code>{e(op)}</code></td><td>{e(svc)}</td><td><code>{e(sp)}</code></td></tr>")

table_cards = []
for name in sorted(schema.keys()):
    fields = schema[name]
    prefix = name.split("_")[0]
    rows = "".join(
        f"<tr><td><code>{e(f['name'])}</code></td><td>{e(f.get('comment') or '')}</td></tr>"
        for f in fields
    )
    table_cards.append(
        f'<details class="tbl-card" id="tbl-{e(name)}" data-search="{e(name)} {e(prefix)}">'
        f"<summary><span class='tbl-name'>{e(name)}</span> <span class='muted'>({len(fields)} cột · {e(prefix)}_)</span></summary>"
        f"<table><thead><tr><th>Field C# (Base)</th><th>Mô tả</th></tr></thead><tbody>{rows}</tbody></table></details>"
    )

