def flow_row(steps):
    parts = [flow_step(*s) for s in steps]
    if parts:
        parts[-1] = parts[-1].replace('<div class="flow-arrow" aria-hidden="true">→</div>', "")
    return '<div class="flow-row">' + "".join(parts) + "</div>"


def lane_list(items):
    return "<ol>" + "".join(f"<li>{x}</li>" for x in items) + "</ol>"


def dual_lanes(sw_items, sql_items, tag=""):
    tag_html = f'<p class="lane-tag">{tag}</p>' if tag else ""
    return (
        f'{tag_html}<div class="lane-grid" data-search="{e(tag)}">'
        f'<div class="lane lane-sw"><h4>Luồng phần mềm (UI → code)</h4>{lane_list(sw_items)}</div>'
        f'<div class="lane lane-sql"><h4>Luồng SQL / dữ liệu</h4>{lane_list(sql_items)}</div>'
